import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第四十八卦 井 水風井 坎上巽下","description":"周易 - 第四十八卦 井 水風井 坎上巽下","frontmatter":{"title":"第四十八卦 井 水風井 坎上巽下","description":"周易 - 第四十八卦 井 水風井 坎上巽下"},"headers":[],"relativePath":"classics/zhouyi/049.md","filePath":"classics/zhouyi/049.md"}'),l={name:"classics/zhouyi/049.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="井" tabindex="-1">井 <a class="header-anchor" href="#井" aria-label="Permalink to “井”">​</a></h1><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>改邑不改井，無喪無得，往來井井。汔至，亦未繘井，羸其瓶，兇。</p><h3 id="彖傳" tabindex="-1">彖傳 <a class="header-anchor" href="#彖傳" aria-label="Permalink to “彖傳”">​</a></h3><p>巽乎水而上水，井；井養而不窮也。改邑不改井，乃以剛中也。汔至亦未繘井，未有功也。羸其瓶，是以兇也。</p><h3 id="象傳" tabindex="-1">象傳 <a class="header-anchor" href="#象傳" aria-label="Permalink to “象傳”">​</a></h3><p>木上有水，井；君子以勞民勸相。</p><h3 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h3><p>井泥不食，舊井無禽。象曰：井泥不 食，下也。舊井無禽，時舍也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>井谷射鮒，甕敝漏。象曰：井谷射鮒，無與也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>井渫不食，為我民惻，可用汲，王明，並受其福。象曰：井渫不食，行惻也。求王明，受福也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>井甃，無咎。象曰：井甃無咎，修井也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>井冽，寒泉食。象曰：寒泉之食，中正也。</p><h3 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h3><p>井收勿幕，有孚無吉。象曰：元吉在上，大成也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
